export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const m = inputs.mass;

  const tTop = u / g;
  const tMax = 2 * u / g;
  const tClamped = Math.max(0, Math.min(time, tMax));

  const y = u * tClamped - 0.5 * g * tClamped * tClamped;
  const v = u - g * tClamped;
  const a = -g;
  const F = m * g;
  const yTop = (u * u) / (2 * g);

  let motionState = 'At the top';
  if (tClamped < 0.001) {
    motionState = 'Ready to toss';
  } else if (Math.abs(tClamped - tTop) < 0.01) {
    motionState = 'At the top';
  } else if (tClamped < tTop) {
    motionState = 'Rising';
  } else if (Math.abs(tClamped - tMax) < 0.01) {
    motionState = 'Back at launch height';
  } else {
    motionState = 'Falling';
  }

  const objects = [];

  const leftLane = sdk.panel({
    x: 10,
    y: 30,
    w: 305,
    h: 380,
    title: 'The motion',
    state: motionState,
    id: 'lane.motion'
  });
  objects.push(...leftLane);

  const axisX = 75;
  const axisY = 370;
  const axisLen = 300;
  const maxScaleHeight = 2.2;
  objects.push(
    sdk.axis('axis.height', {
      x: axisX,
      y: axisY,
      length: axisLen,
      orientation: 'y',
      min: 0,
      max: maxScaleHeight,
      ticks: [0, 0.5, 1.0, 1.5, 2.0],
      label: 'Height',
      unit: 'm'
    })
  );

  const ballX = 145;
  const ballY = axisY - (y / maxScaleHeight) * axisLen;

  objects.push(
    sdk.circle('ball.toss', ballX, ballY, 28, {
      role: 'learner'
    })
  );

  const vScale = 18;
  const vecV = sdk.vector('vec.v', {
    x: ballX + 25,
    y: ballY
  }, {
    value: v,
    direction: 'up',
    scale: vScale,
    label: 'v',
    role: 'observed'
  });
  objects.push(...vecV);

  const aScale = 2.5;
  const vecA = sdk.vector('vec.a', {
    x: ballX - 25,
    y: ballY
  }, {
    value: a,
    direction: 'up',
    scale: aScale,
    label: 'a',
    role: 'warning'
  });
  objects.push(...vecA);

  const lines = [
    `v = ${v >= 0 ? '+' : ''}${v.toFixed(2)} m/s`,
    `a = ${a.toFixed(2)} m/s²`,
    `F_g = ${F.toFixed(1)} N`
  ];
  objects.push(sdk.callout(ballX + 60, ballY - 25, lines, { id: 'callout.toss' }));

  const rightLane = sdk.panel({
    x: 325,
    y: 30,
    w: 305,
    h: 380,
    title: 'Velocity over time',
    state: `a = -${g.toFixed(1)} m/s²`,
    id: 'lane.vt'
  });
  objects.push(...rightLane);

  const numPoints = 24;
  const points = [];
  for (let i = 0; i <= numPoints; i++) {
    const pt = (i / numPoints) * 1.8;
    const pv = u - g * pt;
    points.push({ x: pt, y: pv });
  }

  const vtPlot = sdk.plot('plot.vt', {
    x: 335,
    y: 60,
    w: 285,
    h: 330,
    axes: {
      x: { label: 'Time', min: 0, max: 1.8, unit: 's' },
      y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' }
    },
    series: [
      {
        label: 'v(t)',
        kind: 'line',
        points: points
      }
    ]
  });
  objects.push(vtPlot);

  return {
    frame: sdk.frame(objects, { width: 640, height: 420 }),
    quantities: {
      launchSpeed: u,
      gravity: g,
      mass: m,
      apexTime: tTop,
      apexHeight: yTop,
      height: y,
      velocity: v,
      acceleration: a,
      force: F
    },
    readouts: [
      { id: 'velocity', value: v },
      { id: 'acceleration', value: a },
      { id: 'force', value: F },
      { id: 'motionState', value: motionState }
    ]
  };
}
